INSERT INTO `events` VALUES (1,'simposio-mar-2026','Simpósio Instituto MAR — Advocacia Renovada 2026','Grande encontro nacional de juristas e advogados debatendo o futuro da advocacia, honorários, prerrogativas e tecnologia aplicada ao Direito.','2026-11-11 09:00:00','Auditório do Instituto MAR — Brasília/DF (Transmissão On-line HD)',30,'Híbrido','10 Horas Acadêmicas',1,'2026-09-13 17:49:39','2026-09-13 23:49:17'),(2,'curso-simposio-teste','Teste','Descrição','2027-06-26 23:13:00','Local teste',50,'On-line','Informação Adicional',1,'2026-09-13 23:05:34','2026-09-13 23:05:34'),(3,'congresso-prerrogativas-inovacao-2026','I Congresso Brasileiro de Prerrogativas e Inovação Jurídica','Debates de alto nível com lideranças jurídicas abordando prerrogativas da advocacia, segurança nos tribunais e novas tecnologias no processo judicial.','2026-10-28 09:30:00','Brasília / DF',100,'Presencial','12 Horas Acadêmicas',1,'2026-09-13 23:49:17','2026-09-13 23:49:17'),(4,'seminario-ia-etica-profissional','Seminário: Inteligência Artificial e Ética Profissional','Análise prática e aprofundada sobre os limites regulatórios da inteligência artificial generativa, produtividade ética e impactos nos escritórios de advocacia.','2026-11-12 14:00:00','Online ao Vivo',250,'On-line','6 Horas Acadêmicas',1,'2026-09-13 23:49:17','2026-09-13 23:49:17'),(5,'encontro-anual-coordenadores-estaduais','Encontro Anual de Coordenadores Estaduais','Alinhamento de diretrizes nacionais, planejamento estratégico institucional para o biênio e posse oficial dos membros das novas comissões temáticas do MAR.','2026-12-05 10:00:00','São Paulo / SP',60,'Híbrido','8 Horas Acadêmicas',1,'2026-09-13 23:49:17','2026-09-13 23:49:17'),(6,'curso-pratico-defesa-prerrogativas','Curso Prático de Atuação Imediata em Violação de Prerrogativas','Treinamento operacional para advogados sobre providências urgentes diante de recusa de atendimento, retenção indevida de autos ou cerceamento de sustentação.','2026-12-18 19:00:00','Online ao Vivo',150,'On-line','4 Horas Acadêmicas',1,'2026-09-13 23:49:17','2026-09-13 23:49:17');
