INSERT INTO `official_documents` VALUES (1,'Nota Oficial Nº 04/2026','Manifesto em Defesa do Cumprimento Estrito dos Honorários de Sucumbência pelo Poder Judiciário','Pronunciamento técnico encaminhado aos Conselhos de Justiça reforçando os critérios legais do CPC para fixação de honorários.','2026-09-10','NOTA_OFICIAL','https://doweb.rio.rj.gov.br/portal/edicoes/download/14941','2026-09-13 17:49:39','2026-09-13 23:34:44'),(2,'Portaria Nº 02/2026','Instituição da Comissão Especial de Estudos sobre Inteligência Artificial e Advocacia','Ato da Presidência que define a composição e os objetivos do novo comitê técnico permanente.','2026-09-01','PORTARIA','#','2026-09-13 23:27:15','2026-09-13 23:27:15'),(3,'Manifesto Nº 01/2026','Manifesto de Repúdio ao Cerceamento de Prerrogativas em Sustentações Orais','Documento público exigindo o cumprimento do Estatuto da Advocacia e o direito inafastável de sustentação em sessões de julgamento.','2026-08-15','MANIFESTO','#','2026-09-13 23:27:15','2026-09-13 23:27:15'),(4,'Resolução Nº 01/2025','Diretrizes Gerais do Programa Nacional de Mentoria Jurídica e Acompanhamento de Jovens Advogados','Regulamentação interna da concessão de mentorias gratuitas e apoio ao início da carreira jurídica.','2025-12-10','RESOLUCAO','#','2026-09-13 23:27:15','2026-09-13 23:27:15'),(5,'Nota Oficial Nº 03/2026','Nota Pública sobre a Inviolabilidade dos Escritórios de Advocacia e Sigilo dos Clientes','Reafirmação das garantias constitucionais e prerrogativas contidas no Estatuto da Advocacia frente a medidas de busca desmedidas.','2026-08-28','NOTA_OFICIAL','#','2026-09-13 23:27:15','2026-09-13 23:27:15'),(6,'Ato Institucional Nº 02/2026','Criação das Comissões Especiais de Equidade e Prerrogativas no Nordeste','Regulamenta a estrutura de apoio e nomeação dos membros dos núcleos seccionais do MAR.','2026-08-20','ATO_INSTITUCIONAL','#','2026-09-13 23:27:15','2026-09-13 23:27:15'),(7,'Manifesto Nº 02/2026','Manifesto Nacional pela Valorização da Remuneração da Advocacia Dativa no Brasil','Proposição de tabela mínima unificada e pagamento tempestivo aos defensores dativos em todas as Unidades da Federação.','2026-07-15','MANIFESTO','#','2026-09-13 23:27:15','2026-09-13 23:27:15');
